import json
from lib import *
R = J('r40'); b = R['burst']; now, f1, f2 = R['future']
KV = lambda items, hl=(): {'items': items, 'hl': list(hl)}
steps = [
    step("ID 由两段组成:<毫秒时间戳>-<序号>。用 * 让服务器生成,同一毫秒里的第 1、2、3 条依次得到序号 0、1、2。", ids={'values': ['…341-0', '…341-1', '…341-2'], 'cur': [2]}, kv=KV([['XADD a * i 0/1/2', '…341-0, …341-1, …341-2']], ['XADD a * i 0/1/2'])),
    step(f"压力测试:管道连发 {b['n']} 条 XADD,落在 {b['ms']} 个不同毫秒里;最挤的那个毫秒有 {b['mx']} 条,序号一直加到 {b['mx']-1}。序号就是为「同毫秒多条」准备的。", ids={'values': ['ms1: 0…', 'ms2: 0…', '…', f'最挤: 0…{b["mx"]-1}'], 'cur': [3]}, kv=KV([['5000 条', f'{b["ms"]} 个毫秒'], ['同毫秒最多', f'{b["mx"]} 条']], ['同毫秒最多'])),
    step("显式指定 ID 时,必须严格大于当前最大 ID:1000-1 已存在,再写 1000-1、1000-0、999-99 全部被拒;0-0 永远不合法;1000-2 通过。", ids={'values': ['1000-1 ✓', '1000-1 ✗', '1000-0 ✗', '999-99 ✗', '0-0 ✗', '1000-2 ✓'], 'done': [0, 5], 'mark': [1, 2, 3, 4]}, kv=KV([['错误信息', 'equal or smaller than the target stream top item']], ['错误信息'])),
    step("1001-* 让服务器只补序号:第一次得到 1001-0,第二次 1001-1。", ids={'values': ['1001-*', '→ 1001-0', '1001-*', '→ 1001-1'], 'cur': [1, 3]}, kv=KV([['1001-*', '毫秒固定,序号自动递增']], ['1001-*'])),
    step(f"时钟回拨怎么办?把最后一个 ID 造成「未来」(比当前时间大 3600000 ms),再用 * 追加:得到 {f1}、{f2}——不使用当前时间,沿着最后一个 ID 往上加 seq。", ids={'values': ['last: 未来 +1h', f1.split('-')[0][-6:] + '-' + f1.split('-')[1], f2.split('-')[0][-6:] + '-' + f2.split('-')[1]], 'cur': [1, 2]}, kv=KV([['结论', 'ID 永远单调递增,不受系统时钟影响']], ['结论'])),
    step("范围查询:XRANGE r 20 20 匹配 20-0 和 20-1(只给毫秒,序号自动补全为 0 到最大);(20-0 表示开区间(排除);- 和 + 表示最小、最大。", ids={'values': ['10-0', '20-0', '20-1', '30-0'], 'cur': [1, 2]}, kv=KV([['XRANGE r 20 20', '20-0, 20-1'], ['XRANGE r (20-0 +', '20-1, 30-0']], ['XRANGE r 20 20'])),
    step("上限:毫秒和序号各 64 位。把 ID 写成 18446744073709551615-18446744073709551615 成功,之后再 XADD * 报「stream has exhausted the last possible ID」。", ids={'values': ['max-max ✓', '再加 * ✗'], 'cur': [0], 'mark': [1]}, kv=KV([['错误', 'exhausted the last possible ID']], ['错误'])),
    step("XDEL 删掉最后一条 7-0 之后,last-generated-id 仍是 7-0、max-deleted-entry-id 也是 7-0:ID 不会回收,再写 7-0 被拒。", ids={'values': ['5-0', '6-0', '7-0 (已删)'], 'mark': [2]}, kv=KV([['length', '2'], ['entries-added', '3'], ['last-generated-id', '7-0'], ['max-deleted-entry-id', '7-0']], ['last-generated-id'])),
]
A = dict(
    n=40, series='redis', tags='Redis,Stream,Entry ID,真实验证,动画演示',
    desc=f'在本机 Redis 上验证 Stream Entry ID 的规则:<毫秒>-<序号>,同一毫秒最多连续生成到 {b["mx"]-1} 号(5000 条管道写入落在 {b["ms"]} 个毫秒里);显式 ID 必须严格递增;把最后一个 ID 造成未来后 * 仍沿着它递增;ID 是 64+64 位,用尽后再写会报错;XDEL 不会让 ID 回退。',
    lead='Stream 里每条消息都有一个 ID,形如 1790692351341-0。它不只是个编号:它决定了消息的顺序、范围查询怎么写、消费者从哪里继续读。这篇把 ID 的规则一条条在真实 Redis 上验证:自动生成、同毫秒序号、显式指定的限制、时钟回拨、范围写法、上限,以及 XDEL 之后 ID 会不会回收。',
    facts=[(f'{b["mx"]}', f'管道连发 {b["n"]} 条 XADD 时,同一毫秒里最多的条数(序号 0…{b["mx"]-1})'), ('64 + 64 位', '毫秒与序号各 64 位;用满后 XADD * 直接报错'), ('永不回退', '即使 XDEL 了最后一条、或 ID 被造成「未来」')],
    body=[
        sec('自动生成:毫秒 + 序号', '', term('', blk('r40', 1)), '<p>ID 的前半是服务器当前的毫秒时间戳,后半是序号。同一毫秒里的多条消息靠序号区分。</p>',
            term('', blk('r40', 2)), f'<p>为了看序号能加多高,把 {b["n"]} 条 XADD 用管道一次性发出:这些消息只落在 {b["ms"]} 个不同毫秒里,最挤的一毫秒有 {b["mx"]} 条,序号 0 到 {b["mx"]-1}。这个数字取决于这台机器的写入速度,在别的机器上会不同。</p>'),
        sec('显式指定 ID:必须严格递增', '', term('', blk('r40', 3)), '<p>规则:新 ID 必须<b>严格大于</b>流里当前最大的 ID(等于也不行);<code>0-0</code> 永远不合法。可以只指定毫秒、序号写 <code>*</code>:1001-* 第一次得到 1001-0,第二次 1001-1。</p>'),
        sec('时钟被拨回去了会怎样', '', term('', blk('r40', 4)), f'<p>我没有真的去改系统时钟,而是用等价的办法:先写一条「未来一小时」的 ID,再用 <code>*</code> 追加。结果两条新消息分别是 {f1}、{f2}——服务器没有用当前时间(比它小),而是沿着最后一个 ID 的毫秒继续增加序号。这说明 <code>*</code> 的规则是「取当前时间与最后 ID 中较大的,毫秒相同则序号加 1」,所以 ID 在一个 Stream 内永远单调递增。<b>代价:</b>一旦某次写入用了很大的显式 ID,后面所有自动 ID 都会被它「拖着走」。</p>'),
        sec('范围查询里 ID 怎么写', '', term('', blk('r40', 5)), '<p>只写毫秒(<code>20</code>)时,起点补 <code>-0</code>、终点补最大序号,所以 <code>XRANGE r 20 20</code> 命中 20-0 和 20-1 两条。前面加 <code>(</code> 表示排除这个 ID;<code>-</code> 和 <code>+</code> 是最小和最大;XREVRANGE 的起止参数顺序反过来(先写大的)。</p>'),
        sec('上限与 XDEL', '', term('', blk('r40', 6)), '<p>毫秒和序号各是 64 位无符号整数;把 ID 写成两个都是 2⁶⁴−1 之后,再用 <code>*</code> 追加直接报错;超过 64 位的数字被当成非法 ID。</p>', term('', blk('r40', 7)),
            '<p><code>XDEL</code> 删掉了 7-0,<code>length</code> 从 3 变 2,但 <code>entries-added</code> 仍是 3,<code>last-generated-id</code> 和 <code>max-deleted-entry-id</code> 都是 7-0,再写 7-0 被拒绝。ID 一旦发出就不会回收——这也是消费者可以靠「上次读到哪个 ID」续读的前提。</p>'),
        sec('分步演示:ID 的规则', '每一步对应上面的一段真实输出', demo('Stream Entry ID', [('ids', 'chips', '相关的 ID'), ('kv', 'kv', '结论 / 报错')], steps, '本步涉及的 ID')),
    ],
    refs=[ENV_R, '没有验证:真实的系统时钟回拨(用「未来 ID」等价模拟,没有改系统时间)、集群/复制下 ID 的生成差异、Redis 8 新增的幂等相关字段(XINFO 里的 idmp-*)。同一毫秒最多条数取决于机器速度'],
)
